def generate_good_numbers(N):
    """Generates distinct sums x^2 + y^2 where 1 <= x < y <= N."""
    good_numbers = set()
    for x in range(1, N + 1):
        for y in range(x + 1, N + 1):
            good_numbers.add(x*x + y*y)
    return sorted(list(good_numbers))

# We need enough numbers to ensure we pass the 20th smallest. Let's check up to N=10.
# 10^2 + 9^2 = 181. This should be sufficient.
sorted_numbers = generate_good_numbers(10)
print(f"All generated numbers: {sorted_numbers}")
if len(sorted_numbers) >= 20:
    print(f"20th smallest: {sorted_numbers[19]}")
else:
    print("Not enough numbers generated yet.")

